set +x; set -eu; umask 077; [ "$GUACAMOLE_HOME" = /dev/shm/stackkits-guacamole ]; [ "$(stat -f -c %T /dev/shm)" = tmpfs ]; [ "$STACKKITS_OWNER_PASSWORD_FILE" = /run/secrets/owner-password ]; [ -s "$STACKKITS_OWNER_PASSWORD_FILE" ]; [ -n "$STACKKITS_REMOTE_CONNECTION_XML" ]; [ ! -L "$GUACAMOLE_HOME" ]; mkdir -p "$GUACAMOLE_HOME"; chmod 700 "$GUACAMOLE_HOME"; sum=$(sha256sum < "$STACKKITS_OWNER_PASSWORD_FILE"); hash=${sum%% *}; [ "${#hash}" = 64 ]; case "$hash" in *[!0-9a-f]*) exit 1 ;; esac; mapping=$(mktemp "$GUACAMOLE_HOME/.user-mapping.XXXXXX"); trap 'rm -f "$mapping"' EXIT HUP INT TERM; printf '<?xml version="1.0" encoding="UTF-8"?><user-mapping><authorize username="owner" password="%s" encoding="sha256">%s</authorize></user-mapping>\n' "$hash" "$STACKKITS_REMOTE_CONNECTION_XML" > "$mapping"; chmod 600 "$mapping"; mv -f "$mapping" "$GUACAMOLE_HOME/user-mapping.xml"; trap - EXIT HUP INT TERM; unset hash sum mapping STACKKITS_REMOTE_CONNECTION_XML STACKKITS_OWNER_PASSWORD_FILE; exec /opt/guacamole/bin/entrypoint.sh